/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 t=f.read_text(); page='?'; hits=[]
 for l in t.splitlines():
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search('texas',l,re.I): hits.append((page,l.strip()))
 print(f.name, '\\n', '\\n'.join(f'p. {p}: {l}' for p,l in hits) if hits else 'NO TEXAS MENTION')
PY"

